/**
 * @file Links a combobox input to its listbox by id.
 *
 * The input and the options can hydrate as separate Astro islands in either order, so both parts register into one store keyed by id.
 */
import { omitEmpty } from '@splendidlabz/utils'
import { addListeners, isTab, removeListeners } from '@splendidlabz/utils/dom'
import { initFloating } from '../../Disclosure/Popover/floating.js'
import {
  clearHighlight,
  getAdjacentOption,
  getHighlightedOption,
  getVisibleOptions,
  highlightOption,
  prepareOptions,
  selectOption,
  showOptionCount,
} from './listbox.js'
import { canSelectOption, deselect } from './select.svelte.js'

// ========================================
// Shared state
// ========================================
/**
 * @type {Combobox[]}
 */
const comboboxes = $state([])

/**
 * getCombobox
 * Gets the combobox registered under an id.
 *
 * @typedef {object} Combobox
 * @property {string} id Id of the options wrapper
 * @property {Record<string, any>} state Holds `phase`: closed, open or closing
 * @property {Record<string, any>} nodes Each part registers its own nodes
 * @property {Record<string, any>} options
 * @property {ReturnType<typeof initFloating>} [floating]
 * @property {ResizeObserver} [resizeObserver] Keeps open options as wide as the box
 * @property {() => void} [stopClosing] Ends the fade, leaving the options shown
 *
 * @param {string} id
 * @returns {Combobox | undefined}
 */
export function getCombobox(id) {
  return comboboxes.find(combobox => combobox.id === id)
}

/**
 * initCombobox
 * Registers one part of a combobox, merging it with parts already registered.
 *
 * @param {object} opts
 * @param {string} opts.id Id of the options wrapper
 * @param {object} [opts.state]
 * @param {object} [opts.nodes]
 * @param {object} [opts.options]
 * @returns {Combobox}
 */
export function initCombobox({ id, state = {}, nodes = {}, options = {} }) {
  const combobox = getCombobox(id)
  if (!combobox) {
    comboboxes.push({
      id,
      state,
      nodes: omitEmpty(nodes, { shallow: true }),
      options,
    })
    // The store wraps what was pushed in a proxy, so the entry is read back
    return /** @type {Combobox} */ (getCombobox(id))
  }

  combobox.state = { ...combobox.state, ...omitEmpty(state) }
  combobox.nodes = { ...combobox.nodes, ...omitEmpty(nodes, { shallow: true }) }
  combobox.options = { ...combobox.options, ...omitEmpty(options) }
  return combobox
}

// ========================================
// Actions
// ========================================
/**
 * comboboxInput
 * Lets an input or a button open, move through and select the options it targets.
 *
 * @param {HTMLInputElement | HTMLButtonElement} node
 * @param {object} [props]
 * @param {object} [props.options]
 * @param {boolean} [props.options.loop] Wrap past either end
 * @param {(option: HTMLElement) => void} [props.options.onselect] Receives the selected option
 * @param {(selected: any) => void} [props.options.onselectedchange] Receives the selection after each change
 */
export function comboboxInput(node, props = {}) {
  const id = /** @type {string} */ (node.getAttribute('target'))
  const combobox = initCombobox({
    id,
    nodes: { input: node },
    options: { loop: false, ...omitEmpty(props.options) },
  })

  setInitialPhase(combobox)

  const listeners = [
    { event: 'keydown', node, handler: onKeydown },
    { event: 'focusout', node, handler: onFocusout },
    { event: 'chipremove', node, handler: onChipremove },
  ]

  addListeners(listeners)

  return {
    /**
     * update
     * Takes the input's new options.
     *
     * @param {typeof props} [nextProps]
     */
    update(nextProps = {}) {
      Object.assign(combobox.options, omitEmpty(nextProps.options))
    },
    destroy() {
      removeListeners(listeners)
      removeComboboxNodes({ combobox, names: ['input'] })
    },
  }

  /**
   * onKeydown
   * Opens, moves through, selects and closes the options.
   *
   * @param {KeyboardEvent} event
   */
  function onKeydown(event) {
    const { listbox } = combobox.nodes
    if (!listbox) return
    if (!canChangeSelection(combobox)) return

    const { key } = event
    const isOpen = isComboboxOpen(combobox)

    if (key === 'ArrowDown' || key === 'ArrowUp') {
      event.preventDefault()

      // An arrow means the options are wanted, so it also ends a close still fading
      stopClosingCombobox(combobox)

      if (!isOpen) {
        if (getVisibleOptions(listbox).length) openCombobox(combobox)
        return
      }

      const option = getAdjacentOption({
        listbox,
        direction: key === 'ArrowDown' ? 'next' : 'prev',
        loop: combobox.options.loop,
      })
      if (option) highlight(combobox, option, { behaviour: 'instant' })
      return
    }

    if (key === 'Escape' && isOpen) {
      event.preventDefault()
      closeCombobox(combobox)
      return
    }

    // Backspace on empty text takes the last chip off
    if (key === 'Backspace' && combobox.options.multiple && !node.value) {
      const lastSelected = combobox.state.selected.at(-1)
      if (lastSelected) deselect({ combobox, value: lastSelected.value })
      return
    }

    const highlightedOption = getHighlightedOption(listbox)

    // An exact match closes a single select, and Enter still picks it
    if (key === 'Enter') {
      // Create sorts last, so it heads the list only when nothing matched — and that is the only time Enter takes it
      const [firstOption] = getVisibleOptions(listbox)
      const createOption =
        firstOption?.dataset.create === undefined ? null : firstOption

      const option =
        highlightedOption ?? combobox.options.getTypedOption?.() ?? createOption
      // Enter submits only from a closed list that picks nothing
      if (isOpen || option) event.preventDefault()

      if (option) commitSelection(combobox, option)
      // An option already says this text, so the field is cleared for the next one
      else if (combobox.options.multiple && combobox.state.hasExactMatch)
        writeInputText(combobox, '')

      return
    }

    if (!isOpen) return

    if (isTab(event) && highlightedOption) {
      commitSelection(combobox, highlightedOption)
    }
  }

  /**
   * onFocusout
   * Puts the selected label back and closes the options.
   *
   * Text matching no option never stands as the answer.
   */
  function onFocusout() {
    if (node instanceof HTMLInputElement) {
      const text = combobox.options.multiple
        ? ''
        : (combobox.state.selected[0]?.label ?? '')
      writeInputText(combobox, text)
    }
    if (combobox.nodes.listbox) closeCombobox(combobox)
  }

  /**
   * onChipremove
   * Takes the removed chip off the selection, and puts focus back here.
   *
   * @param {CustomEvent<{ value: string }>} event
   */
  function onChipremove(event) {
    deselect({ combobox, value: event.detail.value })
    node.focus()
  }
}

/**
 * comboboxOptions
 * Registers the options a combobox input targets.
 *
 * @param {HTMLElement} node Wrapper holding the listbox
 * @param {object} [props]
 * @param {boolean} [props.multiple] Let more than one option be selected
 * @param {number} [props.size] How many options to show before scrolling
 */
export function comboboxOptions(node, props = {}) {
  const listbox = /** @type {HTMLElement} */ (
    node.querySelector('[role="listbox"]')
  )
  /** @type {HTMLElement | null} */
  const check = node.querySelector('.option-check-source > .option-check')
  let multiple = props.multiple
  let size = props.size
  prepareOptions({ listbox, multiple, check })
  showOptionCount({ listbox, size })

  // Search results and created values are added after this runs, so they're prepared as they arrive
  const optionsObserver = new MutationObserver(() => {
    prepareOptions({ listbox, multiple, check })
    showOptionCount({ listbox, size })
  })
  optionsObserver.observe(listbox, { childList: true })

  const combobox = initCombobox({
    id: node.id,
    nodes: { listbox, popover: node.hasAttribute('popover') ? node : null },
    options: { size },
  })

  setInitialPhase(combobox)

  /** @type {number | null} */
  let lastPointerX = null
  /** @type {number | null} */
  let lastPointerY = null

  const listeners = [
    { event: 'pointerdown', node, handler: keepInputFocus },
    { event: 'pointermove', node: listbox, handler: highlightHoveredOption },
    { event: 'pointerup', node: listbox, handler: selectReleasedOption },
  ]

  addListeners(listeners)

  return {
    /**
     * update
     * Prepares options Svelte added, and takes `multiple` once the input registers it.
     *
     * @param {typeof props} [nextProps]
     */
    update(nextProps = {}) {
      multiple = nextProps.multiple
      size = nextProps.size
      prepareOptions({ listbox, multiple, check })
      showOptionCount({ listbox, size })
    },
    destroy() {
      removeListeners(listeners)
      optionsObserver.disconnect()
      removeComboboxNodes({ combobox, names: ['listbox', 'popover'] })
    },
  }

  /**
   * keepInputFocus
   * Stops a press inside the list from blurring the input.
   *
   * @param {PointerEvent} event
   */
  function keepInputFocus(event) {
    event.preventDefault()
  }

  /**
   * highlightHoveredOption
   * Highlights the option under the pointer.
   *
   * @param {PointerEvent} event
   */
  function highlightHoveredOption(event) {
    if (!canChangeSelection(combobox)) return

    // Scrolling fires pointermove at the resting coordinates, so an option arriving under a still pointer doesn't take the keyboard's place
    const hasMoved =
      event.clientX !== lastPointerX || event.clientY !== lastPointerY
    lastPointerX = event.clientX
    lastPointerY = event.clientY
    if (!hasMoved) return

    const option = getEventOption(event)
    if (option) highlight(combobox, option, { shouldScroll: false })
  }

  /**
   * selectReleasedOption
   * Selects the option the pointer lifts over, so a press on the trigger can drag into the list and release on a choice.
   *
   * @param {PointerEvent} event
   */
  function selectReleasedOption(event) {
    if (!canChangeSelection(combobox)) return

    // A list still fading is on its way out, so a release that lands on it picks nothing
    if (combobox.state.phase === 'closing') return

    const option = getEventOption(event)
    if (option) commitSelection(combobox, option)
  }
}

// ========================================
// Methods
// ========================================
/**
 * openCombobox
 * Shows the options under the input's box, as wide as the box.
 *
 * Inline options are always shown, so this only changes popover options. Chips share the box with the input, so the box can change size while the options are open.
 *
 * @param {Combobox} combobox
 * @returns {void}
 */
export function openCombobox(combobox) {
  const { input, popover } = combobox.nodes

  stopClosingCombobox(combobox)
  if (combobox.state.phase === 'open') return

  combobox.state.phase = 'open'
  input.setAttribute('aria-expanded', 'true')

  const box = input.closest('.input-group') ?? input
  function matchBoxWidth() {
    popover.style.width = `${box.getBoundingClientRect().width}px`
  }

  // Hidden until the first position lands, because floating-ui computes it a tick after the popover is shown
  matchBoxWidth()
  popover.style.visibility = 'hidden'
  popover.showPopover()

  combobox.resizeObserver = new ResizeObserver(matchBoxWidth)
  combobox.resizeObserver.observe(box)

  combobox.floating ??= initFloating({
    referenceNode: box,
    floatingNode: popover,
    placement: 'bottom-start',
    offset: 0,
  })
  combobox.floating.update()

  // Options measure 0 while the popover is closed, so the cap is set here, once they have a height
  showOptionCount({
    listbox: combobox.nodes.listbox,
    size: combobox.options.size,
  })

  requestAnimationFrame(() => popover.style.removeProperty('visibility'))
}

/**
 * closeCombobox
 * Hides popover options and clears the highlight.
 *
 * The options stay on screen while they fade, so the combobox still reads as open until the fade ends. A click on the input during the fade closes rather than reopens, and a reopen picks the options up where they are.
 *
 * @param {Combobox} combobox
 * @returns {void}
 */
export function closeCombobox(combobox) {
  const { input, listbox, popover } = combobox.nodes

  clearHighlight(listbox)
  input.removeAttribute('aria-activedescendant')

  // Nothing to close, or a close already running that's left to finish
  if (!popover || combobox.state.phase !== 'open') return

  function onFadeEnd(/** @type {TransitionEvent} */ event) {
    if (event.target !== popover) return
    if (event.propertyName !== 'opacity') return
    hideOptions()
  }

  // Takes the options off screen once they have faded
  function hideOptions() {
    combobox.stopClosing?.()
    combobox.state.phase = 'closed'
    input.setAttribute('aria-expanded', 'false')
    popover.hidePopover()
    combobox.floating?.cleanup()
    combobox.resizeObserver?.disconnect()
  }

  // Nothing to fade — reduced motion, a zero duration, or a test environment
  const duration = fadeDuration(popover)
  if (!duration) return hideOptions()

  // Fades the options out here rather than leaving it to the browser. Safari runs no transition when it tears a popover down, so the list would vanish instead of fading.
  combobox.state.phase = 'closing'
  popover.style.opacity = '0'
  popover.addEventListener('transitionend', onFadeEnd)

  // Covers a fade the engine skips
  const timer = setTimeout(hideOptions, duration + 50)

  combobox.stopClosing = function stopClosing() {
    combobox.stopClosing = undefined
    combobox.state.phase = 'open'
    popover.removeEventListener('transitionend', onFadeEnd)
    clearTimeout(timer)
    popover.style.removeProperty('opacity')
  }
}

/**
 * stopClosingCombobox
 * Ends a close still fading, so the options stay on screen at full strength.
 *
 * @param {Combobox} combobox
 * @returns {void}
 */
export function stopClosingCombobox(combobox) {
  combobox.stopClosing?.()
}

/**
 * fadeDuration
 * Reads how long the options take to fade, in milliseconds.
 *
 * @param {HTMLElement} popover
 * @returns {number}
 */
function fadeDuration(popover) {
  const { transitionDuration, transitionProperty } = getComputedStyle(popover)
  const properties = (transitionProperty ?? '')
    .split(',')
    .map(one => one.trim())
  const durations = (transitionDuration ?? '').split(',').map(one => one.trim())
  const index = properties.indexOf('opacity')
  const duration = durations[index] || durations[0] || '0s'

  const milliseconds = duration.endsWith('ms')
    ? parseFloat(duration)
    : parseFloat(duration) * 1000

  // A test environment reports no transition at all, and NaN would make the timer fire on the next tick
  return Number.isFinite(milliseconds) ? milliseconds : 0
}

/**
 * isComboboxOpen
 * Reads whether the options are on screen, counting a close still fading.
 *
 * @param {Combobox} combobox
 */
export function isComboboxOpen(combobox) {
  return combobox.state.phase !== 'closed'
}

/**
 * highlight
 * Highlights an option and points the input at it.
 *
 * @param {Combobox} combobox
 * @param {HTMLElement} option
 * @param {object} [opts]
 * @param {boolean} [opts.shouldScroll] Scroll option into view
 * @param {ScrollBehavior} [opts.behaviour] How the scroll runs. Falls back to the CSS `scroll-behavior`.
 */
export function highlight(
  combobox,
  option,
  { shouldScroll = true, behaviour } = {},
) {
  highlightOption({
    listbox: combobox.nodes.listbox,
    option,
    shouldScroll,
    behaviour,
  })
  combobox.nodes.input.setAttribute('aria-activedescendant', option.id)
}

/**
 * commitSelection
 * Marks the option chosen, then dispatches `input` so `bind:value` and filtering see the new text.
 *
 * @param {Combobox} combobox
 * @param {HTMLElement} option
 */
export function commitSelection(combobox, option) {
  const { input, listbox } = combobox.nodes

  if (!canSelectOption(combobox, option)) return

  selectOption({ listbox, option })

  // A layer above owns the items, so it gets the element and maps it back.
  combobox.options.onselect?.(option)

  // A button shows its selection through Svelte, not through a value
  if (input instanceof HTMLInputElement) {
    // Selecting one of many leaves the text behind: the selection shows as a chip, and the next one is typed right after it.
    const nextText = combobox.options.multiple
      ? ''
      : /** @type {string} */ (option.dataset.label)
    writeInputText(combobox, nextText)
  }

  if (!combobox.options.multiple) closeCombobox(combobox)
}

/**
 * canChangeSelection
 * Reads whether the input is neither disabled nor readonly.
 *
 * Inline options stay clickable while the input can't change, so the options check this too.
 *
 * @param {Combobox} combobox
 */
function canChangeSelection(combobox) {
  const { input } = combobox.nodes
  if (!input) return true
  return !input.disabled && !input.hasAttribute('readonly')
}

/**
 * writeInputText
 * Writes the input's text, then dispatches `input` so `bind:value` and filtering see it.
 *
 * @param {Combobox} combobox
 * @param {string} text
 */
function writeInputText(combobox, text) {
  const { input } = combobox.nodes
  // Searching skips the text a selection wrote
  combobox.state.selectedText = text
  input.value = text
  input.dispatchEvent(new Event('input', { bubbles: true }))
}

/**
 * setInitialPhase
 * Starts the combobox open when its options are inline, since those are always shown.
 *
 * @param {Combobox} combobox
 */
function setInitialPhase(combobox) {
  const { input, listbox, popover } = combobox.nodes
  if (!input || !listbox) return

  combobox.state.phase = popover ? 'closed' : 'open'
  input.setAttribute('aria-expanded', String(!popover))
}

/**
 * removeComboboxNodes
 * Drops a destroyed part's nodes, and the entry once no part is left.
 *
 * @param {object} opts
 * @param {Combobox} opts.combobox
 * @param {string[]} opts.names Node names the part registered
 */
function removeComboboxNodes({ combobox, names }) {
  // Positioning points at the old nodes, so the next open rebuilds it
  combobox.floating?.cleanup()
  delete combobox.floating
  combobox.resizeObserver?.disconnect()

  for (const name of names) delete combobox.nodes[name]
  if (combobox.nodes.input || combobox.nodes.listbox) return

  comboboxes.splice(comboboxes.indexOf(combobox), 1)
}

/**
 * getEventOption
 * Gets the option an event happened on.
 *
 * @param {Event} event
 * @returns {HTMLElement | null}
 */
function getEventOption(event) {
  return /** @type {HTMLElement} */ (event.target).closest('[role="option"]')
}
